using System;
using System.Collections.Generic;
using System.Linq;
using MCM.Common;
using TaleWorlds.Library;
using AnimusForge.SiegeAftermathIntervention;

namespace AnimusForge;

public enum TerminalSettingType
{
	Bool,
	Integer,
	FloatingInteger,
	Dropdown,
	Text,
	Button,
	Hotkey
}

public sealed class TerminalSettingDef
{
	public string Id { get; }
	public string TabCategory { get; }
	public string GroupName { get; }
	public string DisplayName { get; }
	public string HintText { get; }
	public TerminalSettingType SettingType { get; }
	public float MinValue { get; }
	public float MaxValue { get; }
	public float StepValue { get; }
	public string FormatString { get; }
	public Func<DuelSettings, object> Getter { get; }
	public Action<DuelSettings, object> Setter { get; }
	public Action<DuelSettings> Invoker { get; }
	public Func<DuelSettings, Dropdown<string>> DropdownGetter { get; }

	public TerminalSettingDef(
		string id,
		string tabCategory,
		string groupName,
		string displayName,
		string hintText,
		TerminalSettingType settingType,
		float minValue,
		float maxValue,
		float stepValue,
		string formatString,
		Func<DuelSettings, object> getter,
		Action<DuelSettings, object> setter,
		Action<DuelSettings> invoker = null,
		Func<DuelSettings, Dropdown<string>> dropdownGetter = null)
	{
		Id = id ?? "";
		TabCategory = tabCategory ?? "";
		GroupName = TerminalSettingsLocalization.Group(Id, groupName ?? "");
		DisplayName = TerminalSettingsLocalization.Title(Id, displayName ?? "");
		HintText = TerminalSettingsLocalization.Hint(Id, hintText ?? "");
		SettingType = settingType;
		MinValue = minValue;
		MaxValue = maxValue;
		StepValue = stepValue;
		FormatString = formatString ?? "";
		Getter = getter;
		Setter = setter;
		Invoker = invoker;
		DropdownGetter = dropdownGetter;
	}
}

public static class TerminalSettingsRegistry
{
	private static readonly List<TerminalSettingDef> _allDefinitions = new List<TerminalSettingDef>(260);
	private static readonly Dictionary<string, List<TerminalSettingDef>> _byCategory = new Dictionary<string, List<TerminalSettingDef>>(StringComparer.Ordinal);
	private static readonly Dictionary<string, TerminalSettingDef> _byId = new Dictionary<string, TerminalSettingDef>(StringComparer.Ordinal);
	private static bool _initialized;

	static TerminalSettingsRegistry()
	{
		EnsureInitialized();
	}

	public static void EnsureInitialized()
	{
		if (_initialized) return;
		_initialized = true;
		RegisterDefinitions();
		foreach (var def in _allDefinitions)
		{
			_byId[def.Id] = def;
			if (!_byCategory.TryGetValue(def.TabCategory, out var list))
			{
				list = new List<TerminalSettingDef>();
				_byCategory[def.TabCategory] = list;
			}
			list.Add(def);
		}
	}

	public static IReadOnlyList<TerminalSettingDef> AllDefinitions => _allDefinitions;

	public static List<TerminalSettingDef> GetByCategory(string category)
	{
		EnsureInitialized();
		if (string.IsNullOrEmpty(category) || category == "全部") return _allDefinitions.ToList();
		return _byCategory.TryGetValue(category, out var list) ? list.ToList() : new List<TerminalSettingDef>();
	}

	public static TerminalSettingDef GetById(string id)
	{
		EnsureInitialized();
		return id != null && _byId.TryGetValue(id, out var def) ? def : null;
	}

	public static bool SaveSettings()
	{
		return DuelSettings.SaveCurrentSettings();
	}

