		_allDefinitions.Add(new TerminalSettingDef("WorldEntityInjectMaxCount", "AI\u6838\u5FC3", "5. \u77E5\u8BC6\u68C0\u7D22（\u8FD4\u56DE）", "\u5B9E\u4F53\u6CE8\u5165\u4E0A\u9650", "\u63A7\u5236\u6BCF\u6B21\u5BF9\u8BDD\u6700\u591A\u5411 AI \u6CE8\u5165\u591A\u5C11\u4E2A\u4EBA\u7269、\u5730\u70B9、\u5BB6\u65CF\u548C\u738B\u56FD\u68C0\u7D22\u7ED3\u679C。\u7CFB\u7EDF\u6309\u524D\u5904\u7406\u7684\u91CD\u8981\u6027\u987A\u5E8F\u8BA9\u6BCF\u4E2A\u540D\u8BCD\u5148\u5360\u4E00\u4E2A\u6700\u9AD8\u5206\u5B9E\u4F53\u69FD；\u91CD\u540D\u4EBA\u7269\u4F1A\u4F18\u5148\u91C7\u7528\u5176\u4ED6\u540D\u8BCD\u660E\u786E\u9650\u5B9A\u7684\u5BB6\u65CF、\u5176\u6B21\u91C7\u7528\u738B\u56FD，\u518D\u6309\u5176\u4E0E\u5F53\u524D\u804A\u5929 NPC \u7684\u5B9E\u9645\u5927\u5730\u56FE\u8DDD\u79BB\u83B7\u5F97\u6700\u9AD8 0.15 \u7684\u5FAE\u91CF\u52A0\u5206，\u6700\u7EC8\u5206\u5141\u8BB8\u8D85\u8FC7 1.00；\u8303\u56F4\u6216\u4F4D\u7F6E\u4E0D\u53EF\u7528\u65F6\u56DE\u9000\u539F\u59CB\u5F97\u5206。\u82E5\u6700\u9AD8\u5206\u5B9E\u4F53\u5DF2\u88AB\u524D\u9762\u7684\u540D\u8BCD\u5360\u7528，\u5219\u987A\u5EF6\u5230\u7B2C\u4E00\u6761\u672A\u5360\u7528\u5B9E\u4F53。\u53EA\u6709\u4E0A\u9650\u5927\u4E8E\u540D\u8BCD\u6570\u65F6\u624D\u8865\u6B21\u8981\u7ED3\u679C：\u5148\u4E3A\u6700\u9760\u524D\u540D\u8BCD\u8865\u6700\u591A 3 \u6761，\u518D\u4F9D\u6B21\u5904\u7406\u540E\u7EED\u540D\u8BCD。\u9ED8\u8BA4 6。", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.WorldEntityInjectMaxCount, (s, v) => s.WorldEntityInjectMaxCount = Convert.ToInt32(v)));
