		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedVolume", "AI\u6838\u5FC3", "7. \u706B\u5C71\u5F15\u64CE TTS（\u4E13\u7528）", "\u4E3B\u8BED\u97F3\u97F3\u91CF(winmm)", "\u4EC5\u7528\u4E8E\u666E\u901A\u5BF9\u8BDD/\u6D4B\u8BD5\u8BED\u97F3（agentIndex<0）\u7684\u4E3B\u64AD\u653E\u94FE\u8DEF。\u573A\u666F\u558A\u8BDD\u53E3\u578B\u94FE\u8DEF\u8BF7\u8C03“\u53E3\u578B\u94FE\u8DEF\u97F3\u91CF”。", TerminalSettingType.FloatingInteger, 0f, 1f, 0.05f, "0.00", s => s.TtsVolcDedicatedVolume, (s, v) => s.TtsVolcDedicatedVolume = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsVolcDedicatedSpeed", "AI\u6838\u5FC3", "7. \u706B\u5C71\u5F15\u64CE TTS（\u4E13\u7528）", "\u706B\u5C71\u4E13\u7528\u8BED\u901F", "V1 speed_ratio，\u8303\u56F4 [0.1, 2.0]。", TerminalSettingType.FloatingInteger, 0.1f, 2f, 0.05f, "0.00", s => s.TtsVolcDedicatedSpeed, (s, v) => s.TtsVolcDedicatedSpeed = Convert.ToSingle(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsSceneUseWinmmAudible", "AI\u6838\u5FC3", "7. \u706B\u5C71\u5F15\u64CE TTS（\u4E13\u7528）", "\u573A\u666F\u53D1\u58F0\u8D70winmm(\u9632\u56DE\u58F0)", "\u5F00\u542F：\u573A\u666FNPC\u7531winmm\u53D1\u58F0，\u53E3\u578B\u94FE\u8DEF\u4EC5\u9A71\u52A8\u5634\u578B\u5E76\u9759\u97F3。\u5173\u95ED：\u573A\u666FNPC\u6539\u7531\u53E3\u578B\u94FE\u8DEF\u53D1\u58F0，\u53EF\u8C03“\u53E3\u578B\u94FE\u8DEF\u97F3\u91CF”。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.TtsSceneUseWinmmAudible, (s, v) => s.TtsSceneUseWinmmAudible = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("TtsLipSyncSoundEventVolume", "AI\u6838\u5FC3", "7. \u706B\u5C71\u5F15\u64CE TTS（\u4E13\u7528）", "\u53E3\u578B\u94FE\u8DEF\u97F3\u91CF", "\u7528\u4E8E Rhubarb \u53E3\u578B\u9A71\u52A8\u7684 SoundEvent \u97F3\u91CF。\u4EC5\u5F53“\u573A\u666F\u53D1\u58F0\u8D70winmm(\u9632\u56DE\u58F0)”\u5173\u95ED\u65F6\u4F5C\u4E3A\u573A\u666F\u53EF\u542C\u97F3\u91CF。", TerminalSettingType.FloatingInteger, 0f, 1f, 0.05f, "0.00", s => s.TtsLipSyncSoundEventVolume, (s, v) => s.TtsLipSyncSoundEventVolume = Convert.ToSingle(v)));
