		_allDefinitions.Add(new TerminalSettingDef("EnableDeepTrace", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u5F00\u53D1\u8005】\u5F00\u542F\u5168\u4EE3\u7801\u622A\u83B7", "⚠\\ufe0f \u6781\u5176\u786C\u6838\u7684\u8C03\u8BD5\u529F\u80FD！\\n\u5F00\u542F\u540E\u5C06\u622A\u83B7\u6240\u6709 UI \u70B9\u51FB、\u72B6\u6001\u5207\u6362\u548C\u5E95\u5C42\u4EE3\u7801\u5806\u6808(Trace)。\\n\u65E5\u5FD7\u91CF\u6781\u5927，\u4EC5\u4F9B\u5F00\u53D1\u8005\u6392\u67E5\u95EE\u9898\u4F7F\u7528。\u666E\u901A\u73A9\u5BB6\u8BF7\u52FF\u5F00\u542F！", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDeepTrace, (s, v) => s.EnableDeepTrace = Convert.ToBoolean(v)));
