		_allDefinitions.Add(new TerminalSettingDef("EnableAdultHeroPersonaAutoGeneration", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "\u65B0\u6210\u5E74\u4EBA\u7269\u81EA\u52A8\u751F\u6210\u4E2A\u6027\u4E0E\u80CC\u666F", "\u5F00\u542F\u540E，\u5F53\u82F1\u96C4\u5B50\u5973\u6210\u5E74\u65F6，\u81EA\u52A8\u4F7F\u7528\u524D\u5904\u7406API\u4E3A\u5176\u751F\u6210\u4E2A\u6027\u4E0E\u5386\u53F2\u80CC\u666F。\u5DF2\u6709\u4E2A\u6027\u6216\u80CC\u666F\u4E0D\u4F1A\u88AB\u8986\u76D6。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableAdultHeroPersonaAutoGeneration, (s, v) => s.EnableAdultHeroPersonaAutoGeneration = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableModLogicLog", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u65E5\u5FD7】\u5199\u5165 Mod_Logic.txt", "\u603B\u903B\u8F91\u65E5\u5FD7\u5F00\u5173。\u5173\u95ED\u540E\u4E0D\u518D\u5199\u5165 Mod_Logic.txt。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableModLogicLog, (s, v) => s.EnableModLogicLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableVerboseModLogicLog", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u65E5\u5FD7】\u5199\u5165\u8BE6\u7EC6\u8C03\u8BD5\u65E5\u5FD7", "\u53EA\u5728\u6392\u67E5\u95EE\u9898\u65F6\u5F00\u542F。\u5F00\u542F\u540E\u4F1A\u5199\u5165\u66F4\u7EC6\u7684 Mod_Logic \u8BCA\u65AD\u65E5\u5FD7；\u5927\u578B\u5267\u672C\u5927\u5730\u56FE\u53EF\u80FD\u4EA7\u751F\u8F83\u591A\u65E5\u5FD7。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableVerboseModLogicLog, (s, v) => s.EnableVerboseModLogicLog = Convert.ToBoolean(v)));
