		_allDefinitions.Add(new TerminalSettingDef("EnableHitRateStatsLog", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u65E5\u5FD7】\u5199\u5165 HitRate_Stats.txt", "\u547D\u4E2D\u7387\u7EDF\u8BA1\u65E5\u5FD7\u5F00\u5173。\u5173\u95ED\u540E\u4E0D\u518D\u5199\u5165 HitRate_Stats.txt。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableHitRateStatsLog, (s, v) => s.EnableHitRateStatsLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableTokenStatsLog", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u65E5\u5FD7】\u5199\u5165 Token_Stats.txt", "Token \u7EDF\u8BA1\u65E5\u5FD7\u5F00\u5173。\u5173\u95ED\u540E\u4E0D\u518D\u5199\u5165 Token_Stats.txt。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableTokenStatsLog, (s, v) => s.EnableTokenStatsLog = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableEventLogs", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u65E5\u5FD7】\u5199\u5165 Event_Logs.txt", "\u4E8B\u4EF6\u7CFB\u7EDF\u5468\u62A5\u751F\u6210\u65E5\u5FD7\u5F00\u5173。\u5173\u95ED\u540E\u4E0D\u518D\u5199\u5165 Event_Logs.txt。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableEventLogs, (s, v) => s.EnableEventLogs = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnablePerformanceMonitor", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u6027\u80FD】\u542F\u7528\u6027\u80FD\u76D1\u63A7", "\u5F00\u542F\u540E\u6BCF30\u79D2\u5411 Mod_Logic.txt \u5199\u5165 FPS、\u6162\u5E27\u548C\u5E27\u603B\u8017\u65F6。\u53EA\u6709\u540C\u65F6\u5F00\u542F\u8BE6\u7EC6\u8C03\u8BD5\u65E5\u5FD7\u65F6\u624D\u91C7\u96C6\u5404 Tick/Scope \u8017\u65F6；\u666E\u901A\u6E38\u73A9\u4E0D\u627F\u62C5\u9010 Scope \u7EDF\u8BA1\u6210\u672C。\u9ED8\u8BA4\u5173\u95ED。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnablePerformanceMonitor, (s, v) => s.EnablePerformanceMonitor = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableDeferredDailyMaintenance", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u6027\u80FD】\u5EF6\u540E\u65E5\u7ED3\u7EF4\u62A4", "\u5F00\u542F\u540E，\u6BCF\u65E5\u7ED3\u7B97\u53EA\u767B\u8BB0 AnimusForge \u7EF4\u62A4\u4EFB\u52A1，\u8BB0\u5FC6\u603B\u89C8、\u738B\u56FD\u7EF4\u62A4\u548C\u5468\u62A5\u51C6\u5907\u4F1A\u5728\u540E\u7EED\u5927\u5730\u56FE\u4E2D\u6309\u5355\u5E27\u9884\u7B97\u5206\u6279\u6267\u884C。\u7EF4\u62A4\u4F1A\u5728\u6BCF\u4E2A\u5927\u5730\u56FE Tick \u63A8\u8FDB，\u4E0D\u56E0\u884C\u519B\u6682\u505C。\u9ED8\u8BA4\u5F00\u542F。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDeferredDailyMaintenance, (s, v) => s.EnableDeferredDailyMaintenance = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("DailyMaintenanceFrameBudgetMs", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u6027\u80FD】\u65E5\u7ED3\u7EF4\u62A4\u6BCF\u5E27\u9884\u7B97(ms)", "\u5EF6\u540E\u65E5\u7ED3\u7EF4\u62A4\u5F00\u542F\u65F6，\u53EA\u6709\u5B58\u5728\u5F85\u529E\u624D\u6309\u6BCF\u5E27\u9884\u7B97\u63A8\u8FDB；\u4E0D\u4F1A\u56E0\u73A9\u5BB6\u884C\u519B\u6682\u505C。\u9ED8\u8BA4 3；\u8C03\u9AD8\u4F1A\u66F4\u5FEB\u5B8C\u6210\u540E\u53F0\u4EFB\u52A1\u4F46\u66F4\u53EF\u80FD\u4EA7\u751F\u5E27\u5C16\u5CF0。", TerminalSettingType.Integer, 1f, 10f, 1f, "0", s => s.DailyMaintenanceFrameBudgetMs, (s, v) => s.DailyMaintenanceFrameBudgetMs = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableFreezeDumpCapture", "AI\u6838\u5FC3", "4. \u5F00\u53D1\u8005\u9009\u9879", "【\u8BCA\u65AD】AI\u804A\u5929\u5361\u6B7B\u65F6\u751F\u6210\u7EBF\u7A0B Dump", "\u4EC5\u5728 AnimusForge \u81EA\u7531\u5BF9\u8BDD\u7684 AI \u6A21\u5F0F\u6216\u573A\u666F\u558A\u8BDD\u6B63\u5728\u5904\u7406\u65F6，\u4E3B\u7EBF\u7A0B\u8FDE\u7EED 5 \u79D2\u65E0\u5FC3\u8DF3\u624D\u751F\u6210\u7D27\u51D1\u7EBF\u7A0B dump。\u666E\u901A\u5BF9\u8BDD、\u975E AI \u6E38\u73A9\u548C\u539F\u7248\u4FDD\u5B58\u671F\u95F4\u81EA\u52A8\u505C\u7528。\u9ED8\u8BA4\u5F00\u542F。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableFreezeDumpCapture, (s, v) => s.EnableFreezeDumpCapture = Convert.ToBoolean(v)));
