		_allDefinitions.Add(new TerminalSettingDef("EnablePeaceSceneConflict", "\u573A\u666F\u4E92\u52A8", "3. \u573A\u666F\u558A\u8BDD", "\u5141\u8BB8\u73A9\u5BB6\u76F4\u63A5\u653B\u51FB\u89E6\u53D1\u573A\u666F\u51B2\u7A81", "\u5F00\u542F\u540E，\u73A9\u5BB6\u76F4\u63A5\u653B\u51FB\u548C\u5E73\u573A\u666F NPC \u53EF\u4EE5\u89E6\u53D1\u672C\u6A21\u7EC4\u7684\u573A\u666F\u51B2\u7A81。\u5173\u95ED\u540E，\u672C\u6A21\u7EC4\u4E0D\u518D\u628A\u76F4\u63A5\u653B\u51FB\u8F6C\u6210\u573A\u666F\u51B2\u7A81，\u4F24\u5BB3\u7ED3\u7B97\u5B8C\u5168\u4EA4\u56DE\u539F\u7248；\u5BF9\u8BDD\u4E2D\u7684\u5435\u67B6/\u6311\u8845\u4ECD\u7136\u53EF\u4EE5\u89E6\u53D1\u51B2\u7A81\u5347\u7EA7。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnablePeaceSceneConflict, (s, v) => s.EnablePeaceSceneConflict = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("ShoutInputUiBackgroundDropdown", "\u573A\u666F\u4E92\u52A8", "3. \u573A\u666F\u558A\u8BDD", "\u558A\u8BDD\u8F93\u5165\u6846\u5E95\u8272", "\u53EA\u5F71\u54CD\u558A\u8BDD\u8F93\u5165\u6846。\u9ED8\u8BA4\u9ED1\u8272\u900F\u660E；\u4E5F\u53EF\u9009\u767D\u8272\u900F\u660E\u6216\u7C89\u8272\u900F\u660E。", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.ShoutInputUiBackgroundDropdown?.SelectedValue ?? "", (s, v) => { if (s.ShoutInputUiBackgroundDropdown != null && v is int idx && idx >= 0 && idx < s.ShoutInputUiBackgroundDropdown.Count) { var dd = s.ShoutInputUiBackgroundDropdown; dd.SelectedIndex = idx; s.ShoutInputUiBackgroundDropdown = dd; } }, null, s => s.ShoutInputUiBackgroundDropdown));
