		_allDefinitions.Add(new TerminalSettingDef("EnableDuelLoserClanRenownPenalty", "决斗与部队", "2. 决斗规则", "启用决斗家族声望转移", "正式决斗结算后，败者家族实际扣减多少声望，胜者家族就增加多少声望。双方同属一个家族，或任意一方没有家族时不结算。败者声望不会低于 0，也不会强制降低已经获得的家族等级。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableDuelLoserClanRenownPenalty, (s, v) => s.EnableDuelLoserClanRenownPenalty = Convert.ToBoolean(v)));
