		_allDefinitions.Add(new TerminalSettingDef("EnableNpcBattleEquipmentRestore", "角色与同伴", "10. 物品与交易", "NPC 交出装备后自动补回", "开启后，NPC 因给予、交易或战后缴获失去已装备的装备时，满 3 天会恢复到原槽位；原槽位已有其他装备时不会覆盖。关闭后，NPC 仍可交出装备，但不会登记新的恢复任务，也不会执行已登记的恢复任务。重新开启后，已登记任务会继续处理。默认开启。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNpcBattleEquipmentRestore, (s, v) => s.EnableNpcBattleEquipmentRestore = Convert.ToBoolean(v)));
