		_allDefinitions.Add(new TerminalSettingDef("EnableNpcRulerPolicy", "外交与国家", "16. 政策系统/2. NPC统治者政策", "启用NPC统治者政策", "开启后，各 NPC 王国会按设定间隔制定并发布政策。关闭后不再生成新政策，已经生效的政策及其记录不受影响。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNpcRulerPolicy, (s, v) => s.EnableNpcRulerPolicy = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyApiSourceDropdown", "外交与国家", "16. 政策系统/2. NPC统治者政策", "API来源", "复用所选链路现有的 URL、Key、模型和地址解析规则；所选配置不完整时自动回退主 API。明确选择前处理时不受常规前处理 API 开关影响。", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.NpcRulerPolicyApiSourceDropdown?.SelectedValue ?? "", (s, v) => { if (s.NpcRulerPolicyApiSourceDropdown != null && v is int idx && idx >= 0 && idx < s.NpcRulerPolicyApiSourceDropdown.Count) { var dd = s.NpcRulerPolicyApiSourceDropdown; dd.SelectedIndex = idx; s.NpcRulerPolicyApiSourceDropdown = dd; } }, null, s => s.NpcRulerPolicyApiSourceDropdown));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyCheckIntervalDays", "外交与国家", "16. 政策系统/2. NPC统治者政策", "政策检查间隔（天）", "每隔多少个游戏日检查一次是否需要生成新的 NPC 政策。默认 7 天，可在 1—30 天之间调整；没有符合条件的王国时，本轮不会生成政策。", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.NpcRulerPolicyCheckIntervalDays, (s, v) => s.NpcRulerPolicyCheckIntervalDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyIntervalDays", "外交与国家", "16. 政策系统/2. NPC统治者政策", "同一王国政策冷却（天）", "同一 NPC 王国两次政策草案之间至少间隔多少个游戏日。默认 7 天，可在 1—30 天之间调整；待审、通过和否决的正常草案均参与冷却。玩家发布或续约附庸国政策不受冷却限制，但会从当天起按此天数压制目标附庸国的 NPC 统治者政策。", TerminalSettingType.Integer, 1f, 30f, 1f, "0", s => s.NpcRulerPolicyIntervalDays, (s, v) => s.NpcRulerPolicyIntervalDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyFollowSelectedApiTokens", "外交与国家", "16. 政策系统/2. NPC统治者政策", "跟随所选API Token", "开启时使用实际生效 API 来源的最大输出 Tokens；若回退主 API，则改用主 API Token。关闭时始终使用下面的政策自定义值。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.NpcRulerPolicyFollowSelectedApiTokens, (s, v) => s.NpcRulerPolicyFollowSelectedApiTokens = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcRulerPolicyCustomMaxTokens", "外交与国家", "16. 政策系统/2. NPC统治者政策", "自定义最大输出Tokens", "仅在关闭“跟随所选API Token”后使用。只影响 NPC 统治者政策，允许 1000—100000；不修改其他 API 的全局上限。", TerminalSettingType.Integer, 1000f, 100000f, 1f, "0", s => s.NpcRulerPolicyCustomMaxTokens, (s, v) => s.NpcRulerPolicyCustomMaxTokens = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableWorldDiplomacy", "外交与国家", "17. AI外交（测试中）/1. 基础", "启用AI外交", "开启后，各国会自行发布外交宣言、展开交涉并采取外交行动。外交与书记官代笔复用事件与王国叛乱API，配置不完整时回退主API。关闭后恢复原版王国外交决议。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableWorldDiplomacy, (s, v) => s.EnableWorldDiplomacy = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyStartNewGameAtPeace", "外交与国家", "17. AI外交（测试中）/1. 基础", "新游戏开局全大陆和平", "仅对新创建的存档生效，结束开局已有的王国战争。默认关闭；切换此项不会重置当前存档的战争。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.WorldDiplomacyStartNewGameAtPeace, (s, v) => s.WorldDiplomacyStartNewGameAtPeace = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableWorldDiplomacyMapNotifications", "外交与国家", "17. AI外交（测试中）/1. 基础", "外交宣言送达提示", "已送达的外交宣言在左下角显示文字提示，不再弹出右侧通知。关闭不影响交涉、传播、快报素材或王国公告。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableWorldDiplomacyMapNotifications, (s, v) => s.EnableWorldDiplomacyMapNotifications = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyMaxConcurrentOrdinaryRounds", "外交与国家", "17. AI外交（测试中）/2. 事件节奏", "同时进行的普通外交事件上限", "普通自动外交与政策触发共用此上限，默认3场。满额时保留政策待办，已有交涉照常回复和收尾；降低上限不会取消已有事件。每天最多补开1场；玩家主动外交和口头承诺事件不占此名额。", TerminalSettingType.Integer, 1f, 12f, 1f, "0", s => s.WorldDiplomacyMaxConcurrentOrdinaryRounds, (s, v) => s.WorldDiplomacyMaxConcurrentOrdinaryRounds = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyActivityDropdown", "外交与国家", "17. AI外交（测试中）/2. 事件节奏", "单场外交参与国规模", "少量最多2国、适中最多3国、较多最多5国，均包含发起国。只选择有实际外交事项的国家，不强行凑满。默认适中；这是单场人数，不是同时进行的事件数量。", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.WorldDiplomacyActivityDropdown?.SelectedValue ?? "", (s, v) => { if (s.WorldDiplomacyActivityDropdown != null && v is int idx && idx >= 0 && idx < s.WorldDiplomacyActivityDropdown.Count) { var dd = s.WorldDiplomacyActivityDropdown; dd.SelectedIndex = idx; s.WorldDiplomacyActivityDropdown = dd; } }, null, s => s.WorldDiplomacyActivityDropdown));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyRoundLengthDropdown", "外交与国家", "17. AI外交（测试中）/2. 事件节奏", "单场外交目标时长", "决定新事件通常何时收尾：紧凑约15天、标准约21天、从容约28天。可因达成结果提前结束，也可短暂延长完成收尾。默认标准，只影响新事件。", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.WorldDiplomacyRoundLengthDropdown?.SelectedValue ?? "", (s, v) => { if (s.WorldDiplomacyRoundLengthDropdown != null && v is int idx && idx >= 0 && idx < s.WorldDiplomacyRoundLengthDropdown.Count) { var dd = s.WorldDiplomacyRoundLengthDropdown; dd.SelectedIndex = idx; s.WorldDiplomacyRoundLengthDropdown = dd; } }, null, s => s.WorldDiplomacyRoundLengthDropdown));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyCourtMaxDeliveryDays", "外交与国家", "17. AI外交（测试中）/3. 传播", "宣言送达最远王庭（天）", "按距离分配王庭送达时间，本值控制最远王庭的传递时长，也用于新事件一轮接力的传递节奏。不是每个国家都固定等待这么多天。默认7天；数值较低时回复更密集。", TerminalSettingType.Integer, 3f, 14f, 1f, "0", s => s.WorldDiplomacyCourtMaxDeliveryDays, (s, v) => s.WorldDiplomacyCourtMaxDeliveryDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyContinentSpreadDays", "外交与国家", "17. AI外交（测试中）/3. 传播", "宣言传遍大陆（天）", "按距离安排地方贵族和平民获知外交宣言的时间。默认21天；不控制自动开场频率，也不代替王庭送达时间。", TerminalSettingType.Integer, 7f, 42f, 1f, "0", s => s.WorldDiplomacyContinentSpreadDays, (s, v) => s.WorldDiplomacyContinentSpreadDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyDeclarationMinCharacters", "外交与国家", "17. AI外交（测试中）/4. 宣言与代笔", "AI外交宣言最小字数", "AI生成的外交宣言、外交回应与书记官代笔共用此篇幅范围，标点计入。默认最少100字，可在1—1000之间调整；不限制玩家手写编辑。", TerminalSettingType.Integer, 1f, 1000f, 1f, "0", s => s.WorldDiplomacyDeclarationMinCharacters, (s, v) => s.WorldDiplomacyDeclarationMinCharacters = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyDeclarationMaxCharacters", "外交与国家", "17. AI外交（测试中）/4. 宣言与代笔", "AI外交宣言最大字数", "AI生成的外交宣言、外交回应与书记官代笔共用此篇幅范围，标点计入。默认最多500字，可在1—1000之间调整；小于最小字数时按最小字数执行，不限制玩家手写编辑。", TerminalSettingType.Integer, 1f, 1000f, 1f, "0", s => s.WorldDiplomacyDeclarationMaxCharacters, (s, v) => s.WorldDiplomacyDeclarationMaxCharacters = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EditWorldDiplomacyPrompt", "外交与国家", "17. AI外交（测试中）/4. 宣言与代笔", "AI外交与书记官代笔偏好", "编辑外交判断与文风偏好；书记官代笔采用文风要求，忠实扩写玩家已有内容，不自行增加实质条款。留空不添加偏好，固定事实边界和输出规则仍然有效。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditWorldDiplomacyPrompt?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("RestoreDefaultWorldDiplomacyPrompt", "外交与国家", "17. AI外交（测试中）/4. 宣言与代笔", "恢复默认外交与代笔偏好", "确认后恢复模组默认偏好文本。只恢复文案偏好，不重置本页的事件上限、传播、篇幅和保护期设置。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.RestoreDefaultWorldDiplomacyPrompt?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyOffensiveWarCooldownDays", "外交与国家", "17. AI外交（测试中）/5. 战争与提案保护", "再次主动开战间隔（天）", "一个国家主动发动战争后，至少等待多少天才能再次主动发动新战争。默认42天；不限制其他外交宣言的发布频率。", TerminalSettingType.Integer, 7f, 120f, 1f, "0", s => s.WorldDiplomacyOffensiveWarCooldownDays, (s, v) => s.WorldDiplomacyOffensiveWarCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyPeaceProtectionDays", "外交与国家", "17. AI外交（测试中）/5. 战争与提案保护", "和平保护期（天）", "两国议和后，普通外交争端在此期间不能再次引发战争。默认21天；设为0关闭此保护，不影响其他宣战资格限制。", TerminalSettingType.Integer, 0f, 60f, 1f, "0", s => s.WorldDiplomacyPeaceProtectionDays, (s, v) => s.WorldDiplomacyPeaceProtectionDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyTradeAllianceFailedProposalCooldownDays", "外交与国家", "17. AI外交（测试中）/5. 战争与提案保护", "贸易/结盟失败冷却（天）", "贸易或结盟提议未达成后，同一提出国向同一对象国暂时不能再提出相同类型提议。反向提议与另一类型分别计算。默认168天；设为0关闭。", TerminalSettingType.Integer, 0f, 672f, 1f, "0", s => s.WorldDiplomacyTradeAllianceFailedProposalCooldownDays, (s, v) => s.WorldDiplomacyTradeAllianceFailedProposalCooldownDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyThreatComplianceIssuerRelationReward", "外交与国家", "17. AI外交（测试中）/5. 战争与提案保护", "威慑退让国内关系奖励", "对象国明确服从谴责或最后通牒后，发出国正式、非雇佣兵封臣家族的族长与当前国王增加此关系。每次威慑只结算一次。默认10；设为0关闭奖励。", TerminalSettingType.Integer, 0f, 50f, 1f, "0", s => s.WorldDiplomacyThreatComplianceIssuerRelationReward, (s, v) => s.WorldDiplomacyThreatComplianceIssuerRelationReward = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyHistoryCompressionTriggerThousands", "外交与国家", "17. AI外交（测试中）/6. 长期档案（高级）", "外交档案压缩触发值（千估算Tokens）", "长期外交档案达到该估算长度时开始分批压缩。默认800，即约800k Tokens，控制档案积压与压缩频率；不代表每次宣言携带这么多历史。宣言全部输入另有32k估算Tokens上限，压缩每批另有128k输入上限。", TerminalSettingType.Integer, 64f, 900f, 1f, "0", s => s.WorldDiplomacyHistoryCompressionTriggerThousands, (s, v) => s.WorldDiplomacyHistoryCompressionTriggerThousands = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WorldDiplomacyHistoryCompressionTargetThousands", "外交与国家", "17. AI外交（测试中）/6. 长期档案（高级）", "外交档案压缩后目标（千估算Tokens）", "每批压缩后，长期快照和受保护事实的合计目标。默认48，即约48k Tokens，上限60k；宣言只取相关材料，不整份携带快照。实际摘要还受所选API最大输出Tokens限制。", TerminalSettingType.Integer, 8f, 60f, 1f, "0", s => s.WorldDiplomacyHistoryCompressionTargetThousands, (s, v) => s.WorldDiplomacyHistoryCompressionTargetThousands = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableNobleGathering", "外交与国家", "18. 宴会功能", "启用宴会功能", "宴会系统总开关。关闭后停止创建新宴会，正在进行的宴会会在下一个安全的战役小时结算为取消，并安排主人和宾客返程；无需重启游戏。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNobleGathering, (s, v) => s.EnableNobleGathering = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("EnableNpcAutomaticNobleGatherings", "外交与国家", "18. 宴会功能", "启用NPC自动举办宴会", "开启后，符合条件的 NPC 会按王国自动举办宴会。关闭后不再自动创建 NPC 宴会，但玩家仍可主动举办。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.EnableNpcAutomaticNobleGatherings, (s, v) => s.EnableNpcAutomaticNobleGatherings = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("AllowNpcNobleGatheringPlayerInvitations", "外交与国家", "18. 宴会功能", "允许NPC邀请玩家", "开启后，NPC 宴会可以邀请玩家并派信使送信。关闭后只阻止新邀请，已经发出的玩家邀请仍然有效。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AllowNpcNobleGatheringPlayerInvitations, (s, v) => s.AllowNpcNobleGatheringPlayerInvitations = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("ShowNobleGatheringGuestArrivalMessages", "外交与国家", "18. 宴会功能", "显示宾客抵达提示", "控制玩家举办宴会时宾客抵达后的左下角彩色消息。关闭后只隐藏提示，不影响抵达判定、宴会状态或奖励。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.ShowNobleGatheringGuestArrivalMessages, (s, v) => s.ShowNobleGatheringGuestArrivalMessages = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NpcNobleGatheringIntervalDays", "外交与国家", "18. 宴会功能", "NPC宴会间隔（天）", "同一王国两次自动宴会排期之间的游戏天数，默认 21 天。按王国分别计算；修改后用于下一次重新排期。", TerminalSettingType.Integer, 7f, 120f, 1f, "0", s => s.NpcNobleGatheringIntervalDays, (s, v) => s.NpcNobleGatheringIntervalDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("AllowNpcNobleGatheringGovernorInvitations", "外交与国家", "18. 宴会功能", "NPC可以邀请总督", "只影响 NPC 自动生成的宾客名单。关闭时 NPC 不会邀请正在治理定居点的总督；玩家举办宴会时仍可自由邀请总督。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AllowNpcNobleGatheringGovernorInvitations, (s, v) => s.AllowNpcNobleGatheringGovernorInvitations = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("NobleGatheringDurationDays", "外交与国家", "18. 宴会功能", "宴会持续天数", "玩家与 NPC 宴会共用，默认 5 天。修改只影响之后新创建的宴会，已经开始的宴会保持原结束日期。", TerminalSettingType.Integer, 1f, 14f, 1f, "0", s => s.NobleGatheringDurationDays, (s, v) => s.NobleGatheringDurationDays = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NobleGatheringCost", "外交与国家", "18. 宴会功能", "宴会举办费用", "玩家与 NPC 主人共用，费用从实际主人身上扣除。默认 50000 第纳尔；设为 0 表示免费。", TerminalSettingType.Integer, 0f, 500000f, 1f, "0", s => s.NobleGatheringCost, (s, v) => s.NobleGatheringCost = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("NobleGatheringInvitedClanRelationReward", "外交与国家", "18. 宴会功能", "每个受邀家族关系奖励", "玩家与 NPC 宴会共用；主人和每个受邀家族领袖每场只结算一次。默认 5；设为 0 表示不增加关系。修改只影响之后新创建的宴会。", TerminalSettingType.Integer, 0f, 20f, 1f, "0", s => s.NobleGatheringInvitedClanRelationReward, (s, v) => s.NobleGatheringInvitedClanRelationReward = Convert.ToInt32(v)));
        _allDefinitions.Add(new TerminalSettingDef("NewsMode", "外交与国家", DuelSettings.NewsSettingsGroup, "主模式", "选择周报或快报，两种模式互斥；切换保留历史档案。", TerminalSettingType.Dropdown, 0f, 0f, 1f, "", s => s.NewsMode.SelectedValue, (s, v) => { if (v is int index) s.UseWorldBulletin = index != 0; }, null, s => s.NewsMode));
        _allDefinitions.Add(new TerminalSettingDef("AutoGenerateWorldBulletins", "外交与国家", DuelSettings.NewsSettingsGroup + "/快报", "自动发布快报", "关闭后停止新的快报生成，仍记录近期事件供 NPC 知情。与周报自动生成独立。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AutoGenerateWorldBulletins, (s, v) => s.AutoGenerateWorldBulletins = Convert.ToBoolean(v)));
        _allDefinitions.Add(new TerminalSettingDef("EditWorldBulletinWritingRequirements", "外交与国家", DuelSettings.NewsSettingsGroup + "/快报", "快报写作要求", "单独编辑即时快报写作要求，下次请求生效；清空后保留内置格式和事实约束。", TerminalSettingType.Button, 0f, 0f, 0f, "", s => null, null, s => s.EditWorldBulletinWritingRequirements?.Invoke()));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportLengthPreset", "外交与国家", DuelSettings.NewsSettingsGroup + "/周报", "周报篇幅档位", "1=200-400字；2=200-800字；3=200-1200字；4=200-1500字。世界周报和王国周报共用这一档位；默认 2。", TerminalSettingType.Integer, 1f, 4f, 1f, "0", s => s.WeeklyReportLengthPreset, (s, v) => s.WeeklyReportLengthPreset = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportRequestsPerMinute", "外交与国家", DuelSettings.NewsSettingsGroup + "/周报", "每分钟最多生成周报数", "限制开发态周报生成的请求速率。默认 5；最高 20。用于应对部分 API 渠道的 RPM 或并发限制。", TerminalSettingType.Integer, 1f, 20f, 1f, "0", s => s.WeeklyReportRequestsPerMinute, (s, v) => s.WeeklyReportRequestsPerMinute = Convert.ToInt32(v)));
		_allDefinitions.Add(new TerminalSettingDef("AutoGenerateWeeklyReports", "外交与国家", DuelSettings.NewsSettingsGroup + "/周报", "每周自动生成周报", "开启后，系统会在每个新周开始时自动结算上一周，并生成世界周报与各王国周报。第0天会自动写入开局概要作为 week 0 事件。", TerminalSettingType.Bool, 0f, 1f, 1f, "", s => s.AutoGenerateWeeklyReports, (s, v) => s.AutoGenerateWeeklyReports = Convert.ToBoolean(v)));
		_allDefinitions.Add(new TerminalSettingDef("WeeklyReportPopupBodyFontSize", "外交与国家", DuelSettings.NewsSettingsGroup, "报刊弹窗正文字号", "仅影响最近王国周报的大弹窗正文，不影响别的界面。默认 18。", TerminalSettingType.Integer, 12f, 36f, 1f, "0", s => s.WeeklyReportPopupBodyFontSize, (s, v) => s.WeeklyReportPopupBodyFontSize = Convert.ToInt32(v)));
